before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <iostream>
#include <memory>
int main() {
    auto owner = std::make_shared<int>(8);
    std::weak_ptr<int> observer = owner;
    auto second = owner;
    owner.reset();
    if (auto live = observer.lock()) std::cout << *live << '\n';
    second.reset();
    std::cout << std::boolalpha << observer.expired() << '\n';
}

```

